use biome_css_syntax::{AnyCssSelector, CssSyntaxKind};
use biome_rowan::AstNode;
use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;

declare_lint_rule! {
    /// Disallow selectors with too many class selectors.
    ///
    /// Selectors that chain many classes together are harder to read, harder to
    /// override, and more tightly coupled to a specific piece of markup. Keeping the
    /// number of class selectors low encourages simpler, more reusable selectors.
    ///
    /// This rule counts every class selector in an individual selector, including the
    /// ones nested inside pseudo-class functions such as `:not()`, `:is()`, `:has()`
    /// and `:nth-child(... of ...)`. Comma-separated selectors and nested rules are
    /// evaluated independently. Selectors containing SCSS interpolation are ignored.
    ///
    /// This rule does nothing unless the `maxClasses` option is set.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// The following example will show a diagnostic when `maxClasses` is set to `1`:
    ///
    /// ```json,options
    /// {
    ///     "options": {
    ///        "maxClasses": 1
    ///     }
    /// }
    /// ```
    ///
    /// ```css,expect_diagnostic,use_options
    /// .foo.bar {}
    /// ```
    ///
    /// ```css,expect_diagnostic,use_options
    /// .foo .bar {}
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css,use_options
    /// .foo {}
    /// ```
    ///
    /// ## Options
    ///
    /// ### `maxClasses`
    ///
    /// This option sets the maximum number of class selectors allowed in a single
    /// selector. When it is not configured, the rule does not report any diagnostics.
    ///
    pub NoExcessiveSelectorClasses {
        version: "next",
        name: "noExcessiveSelectorClasses",
        language: "css",
        recommended: false,
    }
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssSelector>;
    type State = u16;
    type Signals = Option<Self::State>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        // The rule is inert unless `maxClasses` is explicitly configured.
        let max_classes = ctx.options().max_classes?;

        let selector = ctx.query();
        let syntax = selector.syntax();

        // Only consider individual top-level selectors, i.e. the direct members of a
        // rule's selector list (or a nested rule's relative selector list). This skips
        // the `left`/`right` operands of complex selectors, which are also selectors.
        let parent_kind = syntax.parent().map(|parent| parent.kind());
        if !matches!(
            parent_kind,
            Some(CssSyntaxKind::CSS_SELECTOR_LIST | CssSyntaxKind::CSS_RELATIVE_SELECTOR)
        ) {
            return None;
        }

        // Skip selectors that live inside a pseudo-class/pseudo-element function
        // argument (e.g. `:not(...)`, `:is(...)`, `:has(...)`, `:nth-child(... of ...)`).
        // Their class selectors are counted as part of the enclosing top-level selector.
        if syntax.ancestors().skip(1).any(|ancestor| {
            matches!(
                ancestor.kind(),
                CssSyntaxKind::CSS_PSEUDO_CLASS_SELECTOR
                    | CssSyntaxKind::CSS_PSEUDO_ELEMENT_SELECTOR
            )
        }) {
            return None;
        }

        // Count all class selectors within this selector, and bail out on SCSS
        // interpolation, which makes the selector dynamic.
        let mut class_count: u16 = 0;
        for descendant in syntax.descendants() {
            match descendant.kind() {
                CssSyntaxKind::SCSS_INTERPOLATION => return None,
                CssSyntaxKind::CSS_CLASS_SELECTOR => {
                    class_count = class_count.saturating_add(1);
                }
                _ => {}
            }
        }

        (class_count > max_classes).then_some(class_count)
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let selector = ctx.query();
        let max_classes = ctx.options().max_classes?;
        let found = *state;

        let noun = if max_classes == 1 {
            "class selector"
        } else {
            "class selectors"
        };

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                selector.range(),
                markup! {
                    "Expected this selector to have no more than "{max_classes.to_string()}" "{noun}", but found "{found.to_string()}"."
                },
            )
            .note(markup! {
                "Selectors with too many chained classes are harder to read, override, and reuse."
            })
            .note(markup! {
                "Reduce the number of class selectors in this selector, or split it into simpler selectors."
            }),
        )
    }
}
